//! PR15 Decimate parity. Every `tests/fixtures/pr15_decimate/*.json` holds an input mesh exactly as
//! Blender 5.2.2 stores it and the Blender result of the Decimate modifier on it (generated by
//! `generate.py` in that directory). Each case is rebuilt in Potter and evaluated, and its output must
//! match Blender: positions to 1e-6, face rings as sets of position-keyed rings, UV corners to 1e-6,
//! vertex-group weights to 1e-6, face material indices and edge seam/sharp flags exact, and POINT/EDGE
//! attributes (`INT` and `BOOLEAN` exact; `FLOAT_COLOR` and `BYTE_COLOR` as linear RGBA floats to 1e-6).
//! No Blender install is needed to run these tests.

use std::{collections::BTreeMap, error::Error, fs, path::Path};

use glam::DVec3;
use potter_core::{
    geom::{Mesh, modifiers::evaluate_modifiers},
    model::{Id, Modifier, ModifierRuntime},
};
use serde_json::{Map, Value, json};

type TestResult<T = ()> = Result<T, Box<dyn Error>>;

const TOLERANCE: f64 = 1.0e-6;

#[derive(Clone, Default, Debug)]
struct Report {
    vertex_count: (usize, usize),
    face_count: (usize, usize),
    max_position_error: f64,
    unmatched_rings: usize,
    max_uv_error: f64,
    max_weight_error: f64,
    max_attribute_error: f64,
    material_mismatches: usize,
    edge_flag_mismatches: usize,
    attribute_errors: BTreeMap<String, f64>,
    problems: Vec<String>,
}

impl Report {
    fn passed(&self) -> bool {
        self.problems.is_empty()
            && self.vertex_count.0 == self.vertex_count.1
            && self.face_count.0 == self.face_count.1
            && self.unmatched_rings == 0
            && self.max_position_error <= TOLERANCE
            && self.max_uv_error <= TOLERANCE
            && self.max_weight_error <= TOLERANCE
            && self.max_attribute_error <= TOLERANCE
            && self.material_mismatches == 0
            && self.edge_flag_mismatches == 0
    }
}

/// Blender data type of each generic attribute the oracle writes.
fn attribute_type(name: &str) -> &'static str {
    match name {
        "idx" | "edge_idx" => "INT",
        "flag" | "edge_flag" => "BOOLEAN",
        "bcol" => "BYTE_COLOR",
        _ => "FLOAT_COLOR",
    }
}

fn point(value: &Value) -> TestResult<DVec3> {
    let coords: Vec<f64> = value
        .as_array()
        .ok_or("point must be an array")?
        .iter()
        .map(|coordinate| coordinate.as_f64().ok_or("coordinate must be a number"))
        .collect::<Result<_, _>>()?;
    match coords.as_slice() {
        &[x, y, z] => Ok(DVec3::new(x, y, z)),
        _ => Err("point must have three coordinates".into()),
    }
}

fn indices(value: &Value) -> TestResult<Vec<usize>> {
    value
        .as_array()
        .ok_or("face must be an array")?
        .iter()
        .map(|index| Ok(usize::try_from(index.as_u64().ok_or("index")?)?))
        .collect()
}

fn edge_pair(value: &Value) -> TestResult<[usize; 2]> {
    let pair = indices(value)?;
    match pair.as_slice() {
        &[a, b] => Ok([a, b]),
        _ => Err("edge must have two endpoints".into()),
    }
}

fn edge_key(a: usize, b: usize) -> (usize, usize) {
    (a.min(b), a.max(b))
}

/// Fixture UV rows are Blender V-up values in face/corner order; modifier evaluation uses Potter's
/// canonical face-keyed store with V down.
fn fixture_uv_layers(layers: &[Value], mesh: &Mesh) -> TestResult<Value> {
    let corner_count: usize = mesh.faces.iter().map(|face| face.vertices.len()).sum();
    let mut converted = Vec::with_capacity(layers.len());
    for layer in layers {
        let name = layer["name"].as_str().ok_or("UV layer name missing")?;
        let values = layer["values"]
            .as_array()
            .ok_or("UV layer values missing")?;
        if values.len() != corner_count {
            return Err("UV layer corner count differs from input mesh".into());
        }
        let mut corner = 0;
        let faces = mesh
            .faces
            .iter()
            .map(|face| {
                let end = corner + face.vertices.len();
                let row: Vec<[f64; 2]> = values[corner..end]
                    .iter()
                    .map(|value| {
                        let [u, v] = uv_pair(value);
                        [u, 1.0 - v]
                    })
                    .collect();
                corner = end;
                json!({"face_id": face.id, "uv": row})
            })
            .collect::<Vec<_>>();
        converted.push(json!({"name": name, "faces": faces}));
    }
    let first = converted
        .first()
        .and_then(|layer| layer["name"].as_str())
        .map(str::to_owned);
    Ok(json!({
        "layers": converted,
        "active": first.clone(),
        "render": first,
    }))
}

/// Rebuilds the Blender input in Potter: same vertex and edge order, face material indices, UV corner
/// values, vertex-group weights, edge flags (native `seam`/`sharp` or `blender_edge_flags`) and
/// point/edge attributes.
fn input_mesh(input: &Value) -> TestResult<Mesh> {
    let positions = input["vertices"]
        .as_array()
        .ok_or("vertices missing")?
        .iter()
        .map(point)
        .collect::<TestResult<Vec<_>>>()?;
    let faces = input["faces"]
        .as_array()
        .ok_or("faces missing")?
        .iter()
        .map(indices)
        .collect::<TestResult<Vec<_>>>()?;
    let mut mesh = Mesh::from_positions_and_faces(positions, faces)?;
    let mut remaining = std::mem::take(&mut mesh.edges);
    let mut ordered = Vec::new();
    let mut flags = Vec::new();
    for (pair, flag) in input["edges"]
        .as_array()
        .ok_or("edges missing")?
        .iter()
        .zip(input["edge_flags"].as_array().ok_or("edge_flags missing")?)
    {
        let pair = edge_pair(pair)?;
        let key = edge_key(pair[0], pair[1]);
        let position = remaining
            .iter()
            .position(|edge| {
                let a = mesh.vertices.iter().position(|v| v.id == edge.vertices[0]);
                let b = mesh.vertices.iter().position(|v| v.id == edge.vertices[1]);
                matches!((a, b), (Some(a), Some(b)) if edge_key(a, b) == key)
            })
            .ok_or("Blender edge is missing from the Potter mesh")?;
        let mut edge = remaining.remove(position);
        edge.vertices = [mesh.vertices[pair[0]].id, mesh.vertices[pair[1]].id];
        ordered.push(edge);
        flags.push(json!({"seam": flag[0], "sharp": flag[1]}));
    }
    let native = input["native_edge_flags"]
        .as_bool()
        .ok_or("native_edge_flags missing")?;
    mesh.edges = ordered;
    if native {
        // Native authored store: `seam` and `sharp` keyed by Potter edge id, no `blender_edge_flags`.
        let mut seam = Map::new();
        let mut sharp = Map::new();
        for (edge, flag) in mesh.edges.iter().zip(&flags) {
            seam.insert(format!("e{}", edge.id), flag["seam"].clone());
            sharp.insert(format!("e{}", edge.id), flag["sharp"].clone());
        }
        mesh.attributes.insert(
            "seam".to_owned(),
            json!({"domain": "edge", "type": "bool", "values": seam}),
        );
        mesh.attributes.insert(
            "sharp".to_owned(),
            json!({"domain": "edge", "type": "bool", "values": sharp}),
        );
    } else {
        mesh.attributes
            .insert("blender_edge_flags".to_owned(), Value::Array(flags));
    }
    for (face, material) in mesh.faces.iter_mut().zip(
        input["material_index"]
            .as_array()
            .ok_or("material_index missing")?,
    ) {
        face.material_index = u32::try_from(material.as_u64().ok_or("material index")?)?;
    }
    if let Some(layers) = input.get("uv_layers").and_then(Value::as_array)
        && !layers.is_empty()
    {
        mesh.attributes
            .insert("uv_layers".to_owned(), fixture_uv_layers(layers, &mesh)?);
    }
    let mut groups = Map::new();
    for (name, members) in input["vertex_groups"].as_object().ok_or("groups missing")? {
        let mut weights = Map::new();
        for (index, weight) in members.as_object().ok_or("group members")? {
            let index: usize = index.parse()?;
            weights.insert(format!("v{}", mesh.vertices[index].id), weight.clone());
        }
        groups.insert(name.clone(), Value::Object(weights));
    }
    mesh.attributes
        .insert("vertex_groups".to_owned(), Value::Object(groups));
    let mut attributes = Vec::new();
    for (name, values) in input["point_attributes"]
        .as_object()
        .ok_or("point_attributes missing")?
    {
        attributes.push(json!({
            "name": name,
            "domain": "POINT",
            "data_type": attribute_type(name),
            "values": values,
        }));
    }

    if let Some(edge_attributes) = input["edge_attributes"].as_object() {
        for (name, values) in edge_attributes {
            attributes.push(json!({
                "name": name,
                "domain": "EDGE",
                "data_type": attribute_type(name),
                "values": values,
            }));
        }
    }
    mesh.attributes
        .insert("blender_attributes".to_owned(), Value::Array(attributes));
    Ok(mesh)
}

fn modifier(params: &Value) -> TestResult<Modifier> {
    Ok(Modifier {
        id: Id::new("decimate_parity")?,
        modifier_type: "decimate".to_owned(),
        name: "decimate".to_owned(),
        enabled: true,
        show_viewport: true,
        show_render: true,
        params: params
            .as_object()
            .ok_or("modifier params must be an object")?
            .clone(),
        binding_data: None,
        runtime: ModifierRuntime::default(),
    })
}

/// Index of the smallest vertex in a ring: the start of its canonical rotation.
fn ring_start(ring: &[usize]) -> usize {
    (0..ring.len()).min_by_key(|&i| ring[i]).unwrap_or(0)
}

/// Rotates a ring so it starts at its smallest index, keeping the cyclic order.
fn canonical_ring(ring: &[usize]) -> Vec<usize> {
    let start = ring_start(ring);
    (0..ring.len())
        .map(|i| ring[(start + i) % ring.len()])
        .collect()
}

/// Blender vertex index for each Potter vertex index, by position within [`TOLERANCE`]; `None` when
/// a Potter vertex has no unused Blender partner.
fn match_vertices(blender: &[DVec3], potter: &[DVec3]) -> (Vec<Option<usize>>, f64) {
    let mut matched = vec![None; potter.len()];
    let mut used = vec![false; blender.len()];
    let mut worst = 0.0_f64;
    for (p_index, p) in potter.iter().enumerate() {
        let best = blender
            .iter()
            .enumerate()
            .filter(|(b_index, _)| !used[*b_index])
            .map(|(b_index, b)| (b_index, (*p - *b).length()))
            .min_by(|a, b| a.1.total_cmp(&b.1));
        if let Some((b_index, distance)) = best
            && distance <= TOLERANCE
        {
            used[b_index] = true;
            matched[p_index] = Some(b_index);
            worst = worst.max(distance);
        }
    }
    (matched, worst)
}

fn uv_pair(value: &Value) -> [f64; 2] {
    let pair = value.as_array().map_or(&[][..], Vec::as_slice);
    [
        pair.first().and_then(Value::as_f64).unwrap_or(f64::NAN),
        pair.get(1).and_then(Value::as_f64).unwrap_or(f64::NAN),
    ]
}

/// Error between one Potter attribute value and its Blender value: booleans must match, numbers and colour
/// components differ by their absolute error. A type mismatch or missing value is an error of 1.
fn attribute_error(potter: &Value, blender: &Value) -> f64 {
    match (potter, blender) {
        (Value::Bool(a), Value::Bool(b)) => f64::from(u8::from(a != b)),
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => a
            .iter()
            .zip(b)
            .map(|(a, b)| match (a.as_f64(), b.as_f64()) {
                (Some(a), Some(b)) => (a - b).abs(),
                _ => f64::INFINITY,
            })
            .fold(0.0, f64::max),
        _ => match (potter.as_f64(), blender.as_f64()) {
            (Some(a), Some(b)) => (a - b).abs(),
            _ => 1.0,
        },
    }
}

/// Seam and sharp of every output edge against Blender's, matched by vertex pair. Potter's value comes
/// from the native `seam`/`sharp` attribute (keyed `e<id>`) and from `blender_edge_flags`, whichever are
/// present: a value no store carries, or one that differs from Blender's, is a mismatch.
fn check_edge_flags(
    output: &Mesh,
    blender: &Value,
    matched: &[Option<usize>],
    potter_index: &BTreeMap<u32, usize>,
    report: &mut Report,
) -> TestResult {
    let blender_edges = blender["edges"].as_array().ok_or("edges")?;
    let blender_flags = blender["edge_flags"].as_array().ok_or("edge_flags")?;
    let mut by_pair = BTreeMap::new();
    for (index, pair) in blender_edges.iter().enumerate() {
        let [a, b] = edge_pair(pair)?;
        by_pair.insert(edge_key(a, b), index);
    }
    let compat = output
        .attributes
        .get("blender_edge_flags")
        .and_then(Value::as_array);
    for (p_index, edge) in output.edges.iter().enumerate() {
        let endpoints = edge
            .vertices
            .map(|id| potter_index.get(&id).and_then(|&index| matched[index]));
        // Unmatched endpoints and topology differences are reported by the edge checks in `compare`.
        let [Some(a), Some(b)] = endpoints else {
            continue;
        };
        let Some(&blender_index) = by_pair.get(&edge_key(a, b)) else {
            continue;
        };
        for (slot, name) in ["seam", "sharp"].into_iter().enumerate() {
            let expected = blender_flags
                .get(blender_index)
                .and_then(|flag| flag.get(slot))
                .and_then(Value::as_bool)
                .ok_or("Blender edge flag")?;
            let mut stores = Vec::new();
            if let Some(attribute) = output.attributes.get(name) {
                stores.push(
                    attribute["values"]
                        .get(format!("e{}", edge.id))
                        .and_then(Value::as_bool),
                );
            }
            if let Some(entries) = compat {
                stores.push(entries.get(p_index).and_then(|entry| entry[name].as_bool()));
            }
            if stores.is_empty() {
                report.edge_flag_mismatches += 1;
                if report.problems.len() < 10 {
                    report
                        .problems
                        .push(format!("output edge {p_index} has no {name} flag"));
                }
            }
            for actual in stores {
                if actual != Some(expected) {
                    report.edge_flag_mismatches += 1;
                    if report.problems.len() < 10 {
                        report.problems.push(format!(
                            "output edge {p_index} {name} {actual:?}, Blender {expected}"
                        ));
                    }
                }
            }
        }
    }
    Ok(())
}

fn compare(case: &Value) -> TestResult<Report> {
    let mut report = Report::default();
    let input = &case["input"];
    let blender = &case["blender"];
    let mesh = input_mesh(input)?;
    let output = evaluate_modifiers(&mesh, &[modifier(&case["spec"]["modifier"])?])?;

    let blender_vertices: Vec<DVec3> = blender["vertices"]
        .as_array()
        .ok_or("vertices")?
        .iter()
        .map(point)
        .collect::<TestResult<_>>()?;
    let potter_vertices: Vec<DVec3> = output.vertices.iter().map(|v| v.co).collect();
    report.vertex_count = (blender_vertices.len(), potter_vertices.len());
    let blender_faces: Vec<Vec<usize>> = blender["faces"]
        .as_array()
        .ok_or("faces")?
        .iter()
        .map(indices)
        .collect::<TestResult<_>>()?;
    let blender_materials: Vec<u64> = blender["material_index"]
        .as_array()
        .ok_or("material_index")?
        .iter()
        .map(|material| material.as_u64().ok_or("material index"))
        .collect::<Result<_, _>>()?;
    report.face_count = (blender_faces.len(), output.faces.len());
    if report.vertex_count.0 != report.vertex_count.1 {
        report.problems.push("vertex count differs".to_owned());
    }
    let (matched, worst) = match_vertices(&blender_vertices, &potter_vertices);
    report.max_position_error = worst;
    if matched.iter().any(Option::is_none) {
        report.problems.push("unmatched vertex position".to_owned());
        return Ok(report);
    }
    let potter_index: BTreeMap<u32, usize> = output
        .vertices
        .iter()
        .enumerate()
        .map(|(index, v)| (v.id, index))
        .collect();

    // Potter corner offsets and rings in Blender vertex indices.
    let mut potter_corner_offsets = Vec::with_capacity(output.faces.len());
    let mut potter_rings = Vec::with_capacity(output.faces.len());
    let mut corner_total = 0;
    for face in &output.faces {
        potter_corner_offsets.push(corner_total);
        corner_total += face.vertices.len();
        let ring: Vec<usize> = face
            .vertices
            .iter()
            .map(|id| matched[potter_index[id]].ok_or("vertex"))
            .collect::<Result<_, _>>()?;
        potter_rings.push(ring);
    }
    let potter_layers: Vec<(String, Vec<[f64; 2]>)> = output
        .attributes
        .get("uv_layers")
        .and_then(|store| store["layers"].as_array())
        .into_iter()
        .flatten()
        .map(|layer| {
            let name = layer["name"].as_str().unwrap_or_default().to_owned();
            let mut values = Vec::new();
            if let Some(rows) = layer["faces"].as_array() {
                for face in &output.faces {
                    if let Some(row) = rows
                        .iter()
                        .find(|row| row["face_id"].as_u64() == Some(u64::from(face.id)))
                    {
                        values.extend(row["uv"].as_array().into_iter().flatten().map(|value| {
                            let [u, v] = uv_pair(value);
                            [u, 1.0 - v]
                        }));
                    }
                }
            }
            (name, values)
        })
        .collect();

    let mut blender_offsets = Vec::with_capacity(blender_faces.len());
    let mut total = 0;
    for face in &blender_faces {
        blender_offsets.push(total);
        total += face.len();
    }
    let mut blender_by_ring: BTreeMap<Vec<usize>, usize> = BTreeMap::new();
    for (face_index, ring) in blender_faces.iter().enumerate() {
        blender_by_ring.insert(canonical_ring(ring), face_index);
    }
    let mut matched_faces = vec![false; blender_faces.len()];
    for (face_index, ring) in potter_rings.iter().enumerate() {
        let Some(&blender_face) = blender_by_ring.get(&canonical_ring(ring)) else {
            report.unmatched_rings += 1;
            continue;
        };
        if matched_faces[blender_face] {
            report.unmatched_rings += 1;
            continue;
        }
        matched_faces[blender_face] = true;
        let blender_material = *blender_materials
            .get(blender_face)
            .ok_or("material_index is shorter than the faces")?;
        let potter_material = u64::from(output.faces[face_index].material_index);
        if potter_material != blender_material {
            report.material_mismatches += 1;
            if report.problems.len() < 10 {
                report.problems.push(format!(
                    "face {face_index} material {potter_material}, Blender {blender_material}"
                ));
            }
        }
        let blender_ring = &blender_faces[blender_face];
        let potter_shift = ring_start(ring);
        let blender_shift = ring_start(blender_ring);
        for (layer_name, blender_values) in blender["uv_layers"].as_object().into_iter().flatten() {
            let Some((_, potter_values)) = potter_layers.iter().find(|(n, _)| n == layer_name)
            else {
                report
                    .problems
                    .push(format!("missing UV layer {layer_name}"));
                continue;
            };
            let blender_values = blender_values.as_array().map_or(&[][..], Vec::as_slice);
            for corner in 0..ring.len() {
                let p = potter_values
                    .get(potter_corner_offsets[face_index] + (potter_shift + corner) % ring.len())
                    .copied()
                    .unwrap_or([f64::NAN; 2]);
                let b = blender_values
                    .get(blender_offsets[blender_face] + (blender_shift + corner) % ring.len())
                    .map_or([f64::NAN; 2], uv_pair);
                let error = (p[0] - b[0]).abs().max((p[1] - b[1]).abs());
                report.max_uv_error = if error.is_nan() {
                    f64::INFINITY
                } else {
                    report.max_uv_error.max(error)
                };
                if (error.is_nan() || error > TOLERANCE) && report.problems.len() < 10 {
                    report.problems.push(format!(
                        "UV layer {layer_name} output face {} corner {corner} at Blender vertex {}: Potter {p:?}, Blender {b:?}",
                        output.faces[face_index].id,
                        ring[(potter_shift + corner) % ring.len()]
                    ));
                }
            }
        }
    }
    report.unmatched_rings += matched_faces.iter().filter(|matched| !**matched).count();

    // Vertex-group weights, a missing entry counts as zero.
    let groups = output
        .attributes
        .get("vertex_groups")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    for (group, values) in blender["vertex_groups"].as_object().ok_or("groups")? {
        let values = values.as_array().ok_or("group values")?;
        for (p_index, b_index) in matched.iter().enumerate() {
            let Some(b_index) = b_index else { continue };
            let expected = values[*b_index].as_f64().unwrap_or(0.0);
            let id = output.vertices[p_index].id;
            let actual = groups
                .get(group)
                .and_then(Value::as_object)
                .and_then(|map| map.get(&format!("v{id}")))
                .and_then(Value::as_f64)
                .unwrap_or(0.0);
            report.max_weight_error = report.max_weight_error.max((actual - expected).abs());
        }
    }

    // Point attributes, per output vertex.
    let potter_attributes = output
        .attributes
        .get("blender_attributes")
        .and_then(Value::as_array)
        .map_or(&[][..], Vec::as_slice);
    for (name, blender_values) in blender["point_attributes"]
        .as_object()
        .into_iter()
        .flatten()
    {
        let blender_values = blender_values.as_array().map_or(&[][..], Vec::as_slice);
        let Some(potter_values) = potter_attributes
            .iter()
            .find(|attribute| attribute["name"].as_str() == Some(name))
            .and_then(|attribute| attribute["values"].as_array())
        else {
            report
                .problems
                .push(format!("missing point attribute {name}"));
            continue;
        };
        for (p_index, b_index) in matched.iter().enumerate() {
            let Some(b_index) = b_index else { continue };
            let error = match (potter_values.get(p_index), blender_values.get(*b_index)) {
                (Some(p), Some(b)) => attribute_error(p, b),
                _ => f64::INFINITY,
            };
            report.max_attribute_error = report.max_attribute_error.max(error);
            let by_name = report.attribute_errors.entry(name.clone()).or_default();
            *by_name = by_name.max(error);
        }
    }
    check_edge_flags(&output, blender, &matched, &potter_index, &mut report)?;

    let Some(input_edge_attributes) = input["edge_attributes"]
        .as_object()
        .filter(|attributes| !attributes.is_empty())
    else {
        return Ok(report);
    };
    let blender_edge_attributes = blender["edge_attributes"]
        .as_object()
        .ok_or("edge_attributes")?;
    for name in input_edge_attributes.keys() {
        if !blender_edge_attributes.contains_key(name) {
            report
                .problems
                .push(format!("missing Blender edge attribute {name}"));
            report.max_attribute_error = f64::INFINITY;
            *report.attribute_errors.entry(name.clone()).or_default() = f64::INFINITY;
        }
    }
    // EDGE attributes, matched by undirected output endpoint indices.
    let blender_edges: Vec<[usize; 2]> = blender["edges"]
        .as_array()
        .ok_or("edges")?
        .iter()
        .map(edge_pair)
        .collect::<TestResult<_>>()?;
    if blender_edges.len() != output.edges.len() {
        report.problems.push(format!(
            "edge count differs: Blender {}, Potter {}",
            blender_edges.len(),
            output.edges.len()
        ));
    }
    let mut blender_by_edge = BTreeMap::new();
    for (index, [a, b]) in blender_edges.iter().enumerate() {
        if blender_by_edge.insert(edge_key(*a, *b), index).is_some() {
            report
                .problems
                .push(format!("duplicate Blender output edge {a}-{b}"));
        }
    }
    let mut matched_blender_edges = vec![false; blender_edges.len()];
    let mut edge_matches = Vec::with_capacity(output.edges.len());
    for edge in &output.edges {
        let Some(&a_index) = potter_index.get(&edge.vertices[0]) else {
            report
                .problems
                .push("Potter output edge has an unmatched vertex".to_owned());
            edge_matches.push(None);
            continue;
        };
        let Some(&b_index) = potter_index.get(&edge.vertices[1]) else {
            report
                .problems
                .push("Potter output edge has an unmatched vertex".to_owned());
            edge_matches.push(None);
            continue;
        };
        let (Some(Some(a)), Some(Some(b))) = (matched.get(a_index), matched.get(b_index)) else {
            report
                .problems
                .push("Potter output edge has an unmatched vertex".to_owned());
            edge_matches.push(None);
            continue;
        };
        let Some(&blender_index) = blender_by_edge.get(&edge_key(*a, *b)) else {
            report
                .problems
                .push(format!("unmatched Potter output edge {a}-{b}"));
            edge_matches.push(None);
            continue;
        };
        if matched_blender_edges[blender_index] {
            report
                .problems
                .push(format!("duplicate Potter output edge {a}-{b}"));
        }
        matched_blender_edges[blender_index] = true;
        edge_matches.push(Some(blender_index));
    }
    if matched_blender_edges.iter().any(|matched| !matched) {
        report
            .problems
            .push("unmatched Blender output edge".to_owned());
    }
    let edge_topology_mismatch = blender_edges.len() != output.edges.len()
        || edge_matches.iter().any(Option::is_none)
        || matched_blender_edges.iter().any(|matched| !matched);

    for (name, blender_values) in blender_edge_attributes {
        let blender_values = blender_values.as_array().map_or(&[][..], Vec::as_slice);
        if edge_topology_mismatch {
            report.max_attribute_error = f64::INFINITY;
            *report.attribute_errors.entry(name.clone()).or_default() = f64::INFINITY;
        }
        let Some(potter_values) = potter_attributes
            .iter()
            .find(|attribute| {
                attribute["name"].as_str() == Some(name)
                    && attribute["domain"].as_str() == Some("EDGE")
            })
            .and_then(|attribute| attribute["values"].as_array())
        else {
            report
                .problems
                .push(format!("missing Potter edge attribute {name}"));
            report.max_attribute_error = f64::INFINITY;
            *report.attribute_errors.entry(name.clone()).or_default() = f64::INFINITY;
            continue;
        };
        if potter_values.len() != output.edges.len() {
            report
                .problems
                .push(format!("Potter edge attribute {name} has the wrong length"));
            report.max_attribute_error = f64::INFINITY;
            *report.attribute_errors.entry(name.clone()).or_default() = f64::INFINITY;
        }
        if blender_values.len() != blender_edges.len() {
            report.problems.push(format!(
                "Blender edge attribute {name} has the wrong length"
            ));
            report.max_attribute_error = f64::INFINITY;
            *report.attribute_errors.entry(name.clone()).or_default() = f64::INFINITY;
        }
        for (p_index, b_index) in edge_matches.iter().enumerate() {
            let actual = potter_values.get(p_index);
            let expected = b_index.and_then(|i| blender_values.get(i));
            let error = match (actual, expected) {
                (Some(p), Some(b)) => attribute_error(p, b),
                _ => f64::INFINITY,
            };
            if error > TOLERANCE && report.problems.len() < 10 {
                report.problems.push(format!(
                    "{name} edge {p_index} (Blender edge {b_index:?}): Potter {actual:?}, Blender {expected:?}"
                ));
            }
            report.max_attribute_error = report.max_attribute_error.max(error);
            let by_name = report.attribute_errors.entry(name.clone()).or_default();
            *by_name = by_name.max(error);
        }
    }
    for attribute in potter_attributes
        .iter()
        .filter(|attribute| attribute["domain"].as_str() == Some("EDGE"))
    {
        let name = attribute["name"].as_str().unwrap_or_default();
        if !blender_edge_attributes.contains_key(name) {
            report
                .problems
                .push(format!("extra Potter edge attribute {name}"));
            report.max_attribute_error = f64::INFINITY;
            *report.attribute_errors.entry(name.to_owned()).or_default() = f64::INFINITY;
        }
    }
    Ok(report)
}

#[test]
fn decimate_matches_blender_oracle_for_every_fixture() -> TestResult {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/pr15_decimate");
    let mut paths = Vec::new();
    for entry in fs::read_dir(&directory)? {
        let path = entry?.path();
        if path.extension().and_then(|ext| ext.to_str()) == Some("json") {
            paths.push(path);
        }
    }
    paths.sort();
    let mut failures = Vec::new();
    for path in &paths {
        let case: Value = serde_json::from_str(&fs::read_to_string(path)?)?;
        let name = case["case"].as_str().unwrap_or_default().to_owned();
        let report = match compare(&case) {
            Ok(report) => report,
            Err(error) => {
                failures.push(format!("{name}: error {error}"));
                continue;
            }
        };
        eprintln!(
            "{:<32} {:>3}/{:<3} v  {:>3}/{:<3} f  pos {:.3e}  rings {:>2}  uv {:.3e}  vg {:.3e}  attr {:.3e}  {}",
            name,
            report.vertex_count.1,
            report.vertex_count.0,
            report.face_count.1,
            report.face_count.0,
            report.max_position_error,
            report.unmatched_rings,
            report.max_uv_error,
            report.max_weight_error,
            report.max_attribute_error,
            if report.passed() { "ok" } else { "MISMATCH" }
        );
        if report.max_attribute_error > TOLERANCE {
            eprintln!("  attribute errors: {:?}", report.attribute_errors);
        }
        if !report.passed() {
            failures.push(format!("{name}: {report:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatching cases:\n{}",
        failures.len(),
        failures.join("\n")
    );
    Ok(())
}
